package com.javacodingagent.infrastructure.mq;
import com.javacodingagent.core.port.TaskPublisher; import org.apache.rocketmq.client.apis.*; import org.apache.rocketmq.client.apis.message.MessageBuilder; import org.apache.rocketmq.client.apis.producer.Producer;
public class RocketMqTaskPublisher implements TaskPublisher, AutoCloseable { private final Producer producer; private final ClientServiceProvider provider = ClientServiceProvider.loadService(); private final String topic; public RocketMqTaskPublisher(Producer producer, String topic) { this.producer = producer; this.topic = topic; } public void publish(long taskId, String traceId) { try { MessageBuilder builder = provider.newMessageBuilder().setTopic(topic).setKeys(String.valueOf(taskId)).setTag("CODING_TASK").setBody((taskId + ":" + traceId).getBytes(java.nio.charset.StandardCharsets.UTF_8)); producer.send(builder.build()); } catch (Exception e) { throw new IllegalStateException("Task publish failed", e); } } public void close() throws Exception { producer.close(); } }
